module pulse_detect #(
    parameter s0 = 2'b00,
    parameter s1 = 2'b01,
    parameter s2 = 2'b10,
    parameter s3 = 2'b11
) (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

reg [1:0] state, next_state;

localparam STATE_S0 = 2'b00;
localparam STATE_S1 = 2'b01;
localparam STATE_S2 = 2'b10;
localparam STATE_S3 = 2'b11;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) state <= STATE_S0; else state <= next_state; 
end

always @(*) begin
    case (state)
        STATE_S0: begin
            if (data_in == 1'b0) next_state = STATE_S1; else next_state = STATE_S0; 
        end

        STATE_S1: begin
            if (data_in == 1'b1) next_state = STATE_S2; else next_state = STATE_S1; 
        end

        STATE_S2: begin
            if (data_in == 1'b0) next_state = STATE_S3; else next_state = STATE_S0; 
        end

        STATE_S3: begin
            if (data_in == 1'b1) next_state = STATE_S2; else next_state = STATE_S1; 
        end

        default: next_state = STATE_S0; 
    endcase
end

always @(*) begin
    case (state)
        STATE_S0: data_out = 1'b0; 
        STATE_S1: data_out = 1'b0; 
        STATE_S2: data_out = (data_in == 1'b0) ? 1'b1 : 1'b0; 
        STATE_S3: data_out = 1'b0; 
        default: data_out = 1'b0; 
    endcase
end
endmodule
